package com.dentalcare.api.modules.contactinquiries.controller;
import com.dentalcare.api.config.*; import com.dentalcare.api.exception.GlobalExceptionHandler; import com.dentalcare.api.modules.contactinquiries.dto.response.*; import com.dentalcare.api.modules.contactinquiries.model.*; import com.dentalcare.api.modules.contactinquiries.service.ContactInquiryService; import com.dentalcare.api.security.filter.JwtAuthenticationFilter; import com.dentalcare.api.security.handler.*; import com.dentalcare.api.security.jwt.JwtService; import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest; import org.springframework.context.annotation.Import; import org.springframework.data.domain.PageImpl; import org.springframework.test.context.bean.override.mockito.MockitoBean; import org.springframework.test.web.servlet.MockMvc; import java.time.Instant; import java.util.*; import static org.mockito.ArgumentMatchers.*; import static org.mockito.Mockito.*; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@WebMvcTest(controllers={PublicContactInquiryController.class,ContactInquiryController.class},properties="FRONTEND_URL=http://localhost:3000") @Import({SecurityConfig.class,CorsConfig.class,JwtAuthenticationFilter.class,RestAuthenticationEntryPoint.class,RestAccessDeniedHandler.class,GlobalExceptionHandler.class}) class ContactInquiryControllerSecurityTests { @Autowired MockMvc mvc; @MockitoBean ContactInquiryService service; @MockitoBean JwtService jwt;
 @Test void anonymousCanPostOnlyValidPublicInquiry() throws Exception {when(service.create(any())).thenReturn(new ContactInquiryAcknowledgement(true,"received"));String body="{\"name\":\"Ana\",\"email\":\"ana@test.com\",\"phone\":\"5555-1234\",\"reason\":\"GENERAL\",\"message\":\"Hola\",\"privacyAccepted\":true}";mvc.perform(post("/api/v1/public/contact-inquiries").contentType("application/json").content(body)).andExpect(status().isCreated()).andExpect(jsonPath("$.received").value(true)).andExpect(jsonPath("$.id").doesNotExist());mvc.perform(post("/api/v1/public/contact-inquiries").contentType("application/json").content(body.replace("true","false"))).andExpect(status().isBadRequest());mvc.perform(get("/api/v1/contact-inquiries")).andExpect(status().isUnauthorized());mvc.perform(get("/api/v1/public/contact-inquiries")).andExpect(status().isUnauthorized()); }
 @Test void onlyAdministratorCanManage() throws Exception {UUID actor=UUID.randomUUID(),id=UUID.randomUUID();token("dentist",actor,"ROLE_DENTIST");mvc.perform(get("/api/v1/contact-inquiries").header("Authorization","Bearer dentist")).andExpect(status().isForbidden());token("admin",actor,"ROLE_ADMINISTRATOR");var response=new ContactInquiryResponse(id,"Ana","ana@test.com",null,ContactInquiryReason.GENERAL,"Hola",ContactInquiryStatus.NEW,Instant.now(),Instant.now());when(service.findAll(null,0,20)).thenReturn(new PageImpl<>(List.of(response)));when(service.updateStatus(eq(id),any(),eq(actor))).thenReturn(response);mvc.perform(get("/api/v1/contact-inquiries").header("Authorization","Bearer admin")).andExpect(status().isOk());mvc.perform(patch("/api/v1/contact-inquiries/{id}/status",id).header("Authorization","Bearer admin").contentType("application/json").content("{\"status\":\"IN_REVIEW\"}")).andExpect(status().isOk()); }
 private void token(String raw,UUID id,String... auth){when(jwt.parseAccessToken(raw)).thenReturn(new JwtService.AccessTokenClaims(id,List.of(auth)));} }
